import{_ as n,C as e,o as i,c as t,E as l,a2 as p}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"研究报告生产机 V2.0","description":"基于 Runtime Center V5、Scheduler V3.0、依赖驱动恢复、自检与 GitHub First 的可恢复数字研究员生产系统。","frontmatter":{"title":"研究报告生产机 V2.0","description":"基于 Runtime Center V5、Scheduler V3.0、依赖驱动恢复、自检与 GitHub First 的可恢复数字研究员生产系统。","outline":"deep"},"headers":[],"relativePath":"zh/publications/research-report-production-engine-v2.0.md","filePath":"zh/publications/research-report-production-engine-v2.0.md","lastUpdated":1786258989000}'),o={name:"zh/publications/research-report-production-engine-v2.0.md"};function c(r,a,d,h,u,k){const s=e("ArticleCover");return i(),t("div",null,[l(s,{image:"/assets/covers/research-report-production-engine-v1.svg",kicker:"数字员工工场 · 当前能力发布",title:"研究报告生产机 V2.0",summary:"从按时触发的研究生产线升级为依赖驱动、可追赶、可恢复、自校验的数字研究员 Runtime。",version:"V2.0",status:"2026-08-09 · Current Capability Release",languageHref:"/en/publications/research-report-production-engine-v2.0",languageLabel:"English"}),a[0]||(a[0]=p(`<h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p><strong>研究报告生产机 V2.0</strong> 是一个以 GitHub 为事实源、由 ChatGPT Worker 执行研究工作的数字研究员 Runtime。GitHub cron 只负责唤醒；<code>SCHEDULER.json + Runtime Record</code> 决定现在真正应该执行什么。系统能够发现漏班、从最早未完成阶段按依赖顺序追赶、在依赖解除后恢复可重试的 Blocked 班次，并在每次状态变更后执行机器记录与人类账本自检。</p><h2 id="v2-0-为什么是大版本" tabindex="-1">V2.0 为什么是大版本 <a class="header-anchor" href="#v2-0-为什么是大版本" aria-label="Permalink to &quot;V2.0 为什么是大版本&quot;">​</a></h2><p>V1.x 证明了情报发现、三栏选题、研究技能、15:00 Production、20:00 Publication 与 GitHub Commit Verify 可以组成真实生产线。V2.0 解决的是另一类问题：<strong>生产线本身如何在调度延迟、历史结果异构、依赖未完成和中途阻塞时继续正确运行。</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>V1.x: time-triggered production line</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span>V2.0: dependency-driven recoverable runtime</span></span></code></pre></div><p>V2.0 不再把“某个 cron 被触发”视为任务事实，也不允许后置班次因为时间到了就越过前置班次。</p><h2 id="正式-daily-runtime" tabindex="-1">正式 Daily Runtime <a class="header-anchor" href="#正式-daily-runtime" aria-label="Permalink to &quot;正式 Daily Runtime&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>09:00 Discovery</span></span>
<span class="line"><span>  → Signal Pool</span></span>
<span class="line"><span>10:00 Queue</span></span>
<span class="line"><span>  → Today&#39;s Research Plan</span></span>
<span class="line"><span>11:00 Reading</span></span>
<span class="line"><span>  → Reading Result</span></span>
<span class="line"><span>13:00 Analysis</span></span>
<span class="line"><span>  → Research Object</span></span>
<span class="line"><span>15:00 Production</span></span>
<span class="line"><span>  → Publication Candidate</span></span>
<span class="line"><span>20:00 Publication</span></span>
<span class="line"><span>  → GitHub + Website + Commit Verify + Release</span></span></code></pre></div><p>周日还有第七个当天任务：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>20:30 Weekly</span></span>
<span class="line"><span>  → Weekly Synthesis</span></span></code></pre></div><p>因此周日运营账本必须显示 <strong>7 个任务</strong>。</p><h2 id="核心变化一-cron-是唤醒信号-不是真相源" tabindex="-1">核心变化一：cron 是唤醒信号，不是真相源 <a class="header-anchor" href="#核心变化一-cron-是唤醒信号-不是真相源" aria-label="Permalink to &quot;核心变化一：cron 是唤醒信号，不是真相源&quot;">​</a></h2><p>GitHub Actions 的 schedule 可能延迟或漏掉单次 heartbeat。V2.0 不要求某一个 cron 准时到达，而是每次 heartbeat 都重新读取事实源：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SCHEDULER.json</span></span>
<span class="line"><span>+ Runtime Record</span></span>
<span class="line"><span>+ 当前 Asia/Shanghai 时间</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>哪些班次已经到时？</span></span>
<span class="line"><span>哪些仍然 Waiting？</span></span>
<span class="line"><span>哪些依赖已经 Completed？</span></span>
<span class="line"><span>哪些 Blocked 已经解除依赖？</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>只打开最早的一个可执行欠班</span></span></code></pre></div><p>heartbeat 使用错峰分钟，降低整点拥塞风险；即使连续漏掉多个 heartbeat，下一次恢复时仍能追赶，而不是把任务视为过期。</p><h2 id="核心变化二-严格依赖顺序" tabindex="-1">核心变化二：严格依赖顺序 <a class="header-anchor" href="#核心变化二-严格依赖顺序" aria-label="Permalink to &quot;核心变化二：严格依赖顺序&quot;">​</a></h2><p>Daily 与 Sunday Weekly 的恢复链为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Discovery</span></span>
<span class="line"><span>→ Queue</span></span>
<span class="line"><span>→ Reading</span></span>
<span class="line"><span>→ Analysis</span></span>
<span class="line"><span>→ Production</span></span>
<span class="line"><span>→ Publication</span></span>
<span class="line"><span>→ Weekly (Sunday)</span></span></code></pre></div><p>规则：</p><ul><li>Queue 只有在 Discovery <code>Completed</code> 后才可启动；</li><li>Reading 只有在 Queue <code>Completed</code> 后才可启动；</li><li>Analysis 只有在 Reading <code>Completed</code> 后才可启动；</li><li>Production 只有在 Analysis <code>Completed</code> 后才可启动；</li><li>Publication 只有在 Production <code>Completed</code> 后才可启动；</li><li>Sunday Weekly 只有在 Publication <code>Completed</code> 后才可启动。</li></ul><p>时间到了但依赖未完成时，Scheduler 不越级执行。</p><h2 id="核心变化三-blocked-可以是可恢复状态" tabindex="-1">核心变化三：Blocked 可以是可恢复状态 <a class="header-anchor" href="#核心变化三-blocked-可以是可恢复状态" aria-label="Permalink to &quot;核心变化三：Blocked 可以是可恢复状态&quot;">​</a></h2><p><code>Blocked</code> 不再一律等于永久终态。依赖型阻塞必须记录机器可读的依赖，例如：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Blocked&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;blockedBy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;reading&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>当 <code>reading</code> 后来变为 <code>Completed</code>，Scheduler 可以用受控的 <code>reopen-blocked</code> 路径重新打开 Analysis。普通 Blocked、Completed、Failed、Skipped 不会被任意重开。</p><p>这使恢复成为显式状态转换，而不是人工删除旧结果或伪造 Completed。</p><h2 id="核心变化四-按次序补工作" tabindex="-1">核心变化四：按次序补工作 <a class="header-anchor" href="#核心变化四-按次序补工作" aria-label="Permalink to &quot;核心变化四：按次序补工作&quot;">​</a></h2><p>V2.0 的补班原则不是“现在几点就跑哪个”，而是：</p><ol><li>枚举当天已到正式时间的任务；</li><li>读取每个任务的 durable status；</li><li>排除 Running、Completed、Failed、Skipped；</li><li>对 Waiting 检查前置依赖；</li><li>对 Blocked 检查它是否属于依赖型阻塞，以及依赖是否已经 Completed；</li><li>按正式时间排序；</li><li><strong>一次 heartbeat 只恢复最早的一个可执行班次</strong>；</li><li>后续 heartbeat 继续向后追赶。</li></ol><p>这样即使系统停了数小时，也不会同时打开 Reading、Analysis、Production 造成新的竞态。</p><h2 id="核心变化五-自我检查" tabindex="-1">核心变化五：自我检查 <a class="header-anchor" href="#核心变化五-自我检查" aria-label="Permalink to &quot;核心变化五：自我检查&quot;">​</a></h2><p>每次打开或恢复执行槽后必须执行自检：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Runtime V5 validate</span></span>
<span class="line"><span>→ Markdown ledger render</span></span>
<span class="line"><span>→ Markdown ledger validate</span></span>
<span class="line"><span>→ durable Git commit</span></span>
<span class="line"><span>→ fetch / ancestor verify</span></span>
<span class="line"><span>→ taskStatus == Running verify</span></span>
<span class="line"><span>→ Execution Slot Opened event verify</span></span></code></pre></div><p>班次完成时仍必须满足 <code>runtime-shift-result/v2</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Input</span></span>
<span class="line"><span>Work Result</span></span>
<span class="line"><span>Output</span></span>
<span class="line"><span>Next</span></span>
<span class="line"><span>Metrics</span></span>
<span class="line"><span>Evidence</span></span>
<span class="line"><span>Artifacts</span></span></code></pre></div><p>V2.0 同时兼容仓库已经存在的两类合法结果表达：扁平双语字段和结构化 V5 narrative；历史合法结果不能反过来把 Scheduler 控制面卡死。</p><h2 id="人类账本也是检查面" tabindex="-1">人类账本也是检查面 <a class="header-anchor" href="#人类账本也是检查面" aria-label="Permalink to &quot;人类账本也是检查面&quot;">​</a></h2><p>机器 JSON 是事实源，人类可读 Markdown 是强制投影。投影器必须正确处理结构化 narrative、legacy metric name、字符串 evidence/artifact 和对象 evidence/artifact。</p><p>以下内容视为投影故障：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[object Object]</span></span>
<span class="line"><span>空 Evidence 占位替代真实来源</span></span>
<span class="line"><span>机器状态与 Markdown 状态不一致</span></span>
<span class="line"><span>缺少 Execution Slot Opened / terminal / Commit Verify 时间点</span></span></code></pre></div><h2 id="_2026-08-09-recovery-case" tabindex="-1">2026-08-09 Recovery Case <a class="header-anchor" href="#_2026-08-09-recovery-case" aria-label="Permalink to &quot;2026-08-09 Recovery Case&quot;">​</a></h2><p>V2.0 的恢复机制来自一次真实生产故障，而不是预设演示。</p><p>当天是周日，应运行 7 个任务。09:00 Discovery 与 10:00 Queue 已完成，但 11:00 Reading 未被正常打开；13:00 Analysis 随后在 Reading 未完成时被打开，并按门禁正确产生 Blocked 结果。进一步排查发现：</p><ul><li>GitHub schedule heartbeat 曾出现长时间间隙；</li><li>Scheduler 已能识别 Reading 欠班，但 Runtime V5 校验器不能兼容仓库已有的结构化 shift result；</li><li>Analysis 的 Blocked 若被当成永久终态，即使 Reading 后补完成也无法自动恢复；</li><li>Markdown 投影对结构化 Queue result 会出现 <code>[object Object]</code>。</li></ul><p>修复后：</p><ul><li>Runtime V5 接受现有合法 result 形态；</li><li>Reading 被补开为 Running；</li><li>Analysis 记录 <code>blockedBy: reading</code>；</li><li>Scheduler 增加依赖门禁和 dependency-ready Blocked 重开；</li><li>Markdown 投影恢复可读；</li><li>一次性 hotfix 文件被清理，正式逻辑只保留在 Runtime 与 Scheduler 中。</li></ul><p>这次事故形成了 V2.0 的基本恢复原则：<strong>先恢复事实，再恢复最早依赖，再验证，再向后推进。</strong></p><h2 id="runtime-家族" tabindex="-1">Runtime 家族 <a class="header-anchor" href="#runtime-家族" aria-label="Permalink to &quot;Runtime 家族&quot;">​</a></h2><p>V2.0 继续使用 Runtime Center V5 的四家族边界：</p><ul><li>Daily Runtime；</li><li>Weekly Runtime；</li><li>Academic Runtime；</li><li>Research Program Runtime。</li></ul><p>Program 不占用 Daily 栏目或 Daily 阶段。Academic 仍在周三 16:00 独立运行；Program 仍在周一 12:00 独立运行。</p><h2 id="权威文件" tabindex="-1">权威文件 <a class="header-anchor" href="#权威文件" aria-label="Permalink to &quot;权威文件&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>research/runtime/SCHEDULER.json</span></span>
<span class="line"><span>research/runtime/records/{family}/YYYY/MM/*.json</span></span>
<span class="line"><span>research/runtime/YYYY/MM/YYYY-MM-DD-runtime.md</span></span>
<span class="line"><span>research/runtime/plans/YYYY/MM/YYYY-MM-DD-plan.json</span></span>
<span class="line"><span>scripts/runtime-v5.mjs</span></span>
<span class="line"><span>scripts/runtime-markdown.mjs</span></span>
<span class="line"><span>.github/workflows/research-runtime-scheduler.yml</span></span></code></pre></div><h2 id="下载与验证" tabindex="-1">下载与验证 <a class="header-anchor" href="#下载与验证" aria-label="Permalink to &quot;下载与验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/joinwell52-AI/joinwell52.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> joinwell52</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> runtime:validate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>运行中的真实状态应优先查看 Runtime Center 和当天 Markdown 账本，而不是仅看 Actions 是否出现绿色 Run。</p><h2 id="v1-3-与-v2-0" tabindex="-1">V1.3 与 V2.0 <a class="header-anchor" href="#v1-3-与-v2-0" aria-label="Permalink to &quot;V1.3 与 V2.0&quot;">​</a></h2><p>V1.3 保留为历史能力发布，不回写为 V2.0。V2.0 成为新的 Current Capability Release。</p><table tabindex="0"><thead><tr><th>版本</th><th>运行模型</th></tr></thead><tbody><tr><td>V1.3</td><td>Research Intelligence + 定时研究生产线</td></tr><tr><td><strong>V2.0</strong></td><td><strong>依赖驱动 + 欠班追赶 + Blocked 恢复 + 自校验 Runtime</strong></td></tr></tbody></table><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>研究生产系统真正的可靠性，不是保证每一个外部定时器永远准时，而是即使唤醒延迟、执行中断或依赖暂缺，系统仍能从 durable facts 判断“做到哪里、缺了什么、下一步只能做什么”，并留下可验证的恢复证据。</p>`,61))])}const m=n(o,[["render",c]]);export{b as __pageData,m as default};
